import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String ln;
        while ((ln = br.readLine()) != null) all.append(ln).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken()), width = Integer.parseInt(st.nextToken());
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = st.nextToken();
        List<String> lines = new ArrayList<>();
        int i = 0;
        while (i < n) {
            // greedily take the longest prefix that fits with single spaces
            int end = i, letters = 0;
            while (end < n && letters + words[end].length() + (end - i) <= width) letters += words[end++].length();
            int count = end - i;
            StringBuilder line = new StringBuilder();
            if (end == n || count == 1) {
                for (int j = i; j < end; j++) { if (j > i) line.append(' '); line.append(words[j]); }
                while (line.length() < width) line.append(' ');
            } else {
                int base = (width - letters) / (count - 1), extra = (width - letters) % (count - 1);
                for (int j = i; j < end - 1; j++) {
                    line.append(words[j]);
                    int spaces = base + (j - i < extra ? 1 : 0);
                    for (int s = 0; s < spaces; s++) line.append(' ');
                }
                line.append(words[end - 1]);
            }
            lines.add(line.toString());
            i = end;
        }
        StringBuilder out = new StringBuilder();
        out.append(lines.size()).append('\n');
        for (String l : lines) out.append(l).append('\n');
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	var n, width int
	fmt.Fscan(r, &n, &width)
	words := make([]string, n)
	for i := range words {
		fmt.Fscan(r, &words[i])
	}
	var lines []string
	for i := 0; i < n; {
		// greedily take the longest prefix that fits with single spaces
		end, letters := i, 0
		for end < n && letters+len(words[end])+(end-i) <= width {
			letters += len(words[end])
			end++
		}
		count := end - i
		var line string
		if end == n || count == 1 {
			line = strings.Join(words[i:end], " ")
			line += strings.Repeat(" ", width-len(line))
		} else {
			base, extra := (width-letters)/(count-1), (width-letters)%(count-1)
			var b strings.Builder
			for j := i; j < end-1; j++ {
				b.WriteString(words[j])
				spaces := base
				if j-i < extra {
					spaces++
				}
				b.WriteString(strings.Repeat(" ", spaces))
			}
			b.WriteString(words[end-1])
			line = b.String()
		}
		lines = append(lines, line)
		i = end
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fmt.Fprintln(w, len(lines))
	for _, l := range lines {
		fmt.Fprintln(w, l)
	}
}
